// tsup.config.ts
import { defineConfig } from 'tsup';

export default defineConfig({
  entry: ['src/index.ts', 'src/locale/*.ts'],
  format: ['esm', 'cjs'],
  dts: true,           // gera .d.ts
  sourcemap: true,
  clean: true,
  splitting: false,    // mantém um arquivo por entry
  treeshake: true,
  target: 'es2022',
  external: ['react'], // peer deps nunca bundled
  outExtension: ({ format }) => ({
    js: format === 'cjs' ? '.cjs' : '.js',
  }),
});

// Solução: singleton em globalThis
const KEY = Symbol.for('@ffv/date-helper/registry');
type Registry = Map<string, unknown>;

export function getRegistry(): Registry {
  const g = globalThis as any;
  if (!g[KEY]) g[KEY] = new Map();
  return g[KEY];
}
// Agora ESM e CJS compartilham o mesmo Map real.
